// B12 Paystack Subscribe — Build the initialize-transaction request
// Set PAYSTACK_SECRET_KEY env var in Railway. Use sk_test_xxx for sandbox, sk_live_xxx for live.
// Pre-create plans on Paystack dashboard and set their codes as env vars:
//   PAYSTACK_PLAN_STARTER, PAYSTACK_PLAN_OPERATOR, PAYSTACK_PLAN_COMMAND

const setup = $('Edit Fields — Setup').item.json;
const tier = (setup['tier'] || 'starter').toLowerCase();
const email = (setup['email'] || '').trim();

// Validate email — Paystack requires it
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

// Tier config — monthly recurring (no setup fee in v1; can add via separate one-off charge later)
const TIERS = {
  starter:  { name: 'Starter',  amountZar: 1490 },
  operator: { name: 'Operator', amountZar: 3990 },
  command:  { name: 'Command',  amountZar: 9990 }
};
const tierConfig = TIERS[tier] || TIERS.starter;

const planCode = $env['PAYSTACK_PLAN_' + tier.toUpperCase()] || '';
const reference = 'JN-' + Date.now() + '-' + Math.floor(Math.random() * 10000);

const RETURN_URL = 'https://jarvis-nexus-lead-jkon.vercel.app/thank-you?ref=' + reference;
const CALLBACK_URL = 'https://jarvis-nexus-lead-jkon.vercel.app/thank-you';

const body = {
  email,
  amount: tierConfig.amountZar * 100, // Paystack expects kobo (cents)
  currency: 'ZAR',
  reference,
  callback_url: CALLBACK_URL,
  metadata: { tier, tierName: tierConfig.name, source: 'jarvis-nexus-portal' }
};
if (planCode) body.plan = planCode;

return [{
  json: {
    emailValid,
    email,
    tier,
    tierName: tierConfig.name,
    reference,
    requestBody: body,
    secretKey: $env['PAYSTACK_SECRET_KEY'] || ''
  }
}];

// B12 — Build the auto-redirect HTML using Paystack's authorization_url
const resp = $input.item.json;
const prep = $('Code — Prepare Init').item.json;

const authUrl = (resp && resp['data'] && resp['data']['authorization_url']) || '';
const reference = prep['reference'];
const tierName = prep['tierName'];

if (!authUrl) {
  // Paystack rejected the initialize — return an error page
  const errMsg = (resp && resp['message']) || 'Paystack initialize failed. Check PAYSTACK_SECRET_KEY env var on Railway.';
  const errHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Checkout error</title>'
    + '<style>body{font-family:Arial,sans-serif;background:#08080c;color:#f5f5fa;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:20px;}.card{text-align:center;max-width:480px;padding:40px;border:1px solid rgba(244,63,94,0.3);border-radius:12px;background:#1c1c28;}.label{color:#f43f5e;font-size:11px;letter-spacing:0.18em;font-family:monospace;margin-bottom:10px;}.msg{font-size:15px;color:#a8a8c2;line-height:1.6;}</style>'
    + '</head><body><div class="card"><div class="label">// CHECKOUT ERROR</div><div class="msg">' + errMsg + '</div></div></body></html>';
  return [{ json: { html: errHtml, ok: false } }];
}

const html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Redirecting to Paystack...</title>'
  + '<style>body{font-family:-apple-system,Arial,sans-serif;background:#08080c;color:#f5f5fa;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:20px;}'
  + '.card{text-align:center;padding:40px;max-width:480px;}'
  + '.spinner{display:inline-block;width:36px;height:36px;border:3px solid rgba(99,102,241,0.2);border-top-color:#818cf8;border-radius:50%;animation:spin 800ms linear infinite;margin-bottom:24px;}'
  + '@keyframes spin{to{transform:rotate(360deg);}}'
  + '.label{font-family:monospace;font-size:11px;letter-spacing:0.18em;color:#818cf8;text-transform:uppercase;margin-bottom:10px;font-weight:600;}'
  + '.text{font-size:20px;font-weight:600;margin-bottom:8px;letter-spacing:-0.01em;}'
  + '.sub{font-size:13.5px;color:#a8a8c2;line-height:1.55;margin-bottom:24px;}'
  + '.ref{font-family:monospace;font-size:11px;color:#6b6b85;letter-spacing:0.06em;padding-top:20px;border-top:1px solid rgba(255,255,255,0.06);}</style></head><body>'
  + '<div class="card"><div class="spinner"></div>'
  + '<div class="label">// NSM &middot; ' + tierName.toUpperCase() + '</div>'
  + '<div class="text">Securing your checkout...</div>'
  + '<div class="sub">Redirecting you to Paystack to complete payment.</div>'
  + '<div class="ref">REF &middot; ' + reference + '</div></div>'
  + '<script>window.location.replace(' + JSON.stringify(authUrl) + ');</script>'
  + '<noscript><meta http-equiv="refresh" content="0;url=' + authUrl + '"></noscript>'
  + '</body></html>';

return [{ json: { html, ok: true, authUrl, reference } }];
